#include "../src/engine.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void){const mpc_engine_t*e=mpc_engine();void*s=e->create(NULL);char a[256],b[256];e->get_param(s,"screen_preset",a,sizeof a);assert(strstr(a,"Init Clean"));e->set_param(s,"preset","8");e->get_param(s,"screen_preset",b,sizeof b);assert(strcmp(a,b)&&strstr(b,"NervousKeys"));e->get_param(s,"screen_hint",a,sizeof a);assert(!strcmp(a,"PARTIAL PRESET"));e->set_param(s,"cutoff","0.25");e->get_param(s,"screen_detail",a,sizeof a);assert(strstr(a,"Cutoff")&&strstr(a,"25%"));e->set_param(s,"cutoff","0.75");e->get_param(s,"screen_detail",b,sizeof b);assert(strcmp(a,b)&&strstr(b,"75%"));e->get_param(s,"screen_model",a,sizeof a);e->set_param(s,"osc_type","7");e->get_param(s,"screen_model",b,sizeof b);assert(strcmp(a,b)&&strstr(b,"Two Operator FM"));e->set_param(s,"lfo_rate_free","2.5");e->get_param(s,"screen_detail",b,sizeof b);assert(strstr(b,"2.50 Hz"));e->destroy(s);puts("screen: live preset/name, oscillator, focused knob value, Hz and partial status PASS");}
